from __future__ import annotations

import json
import math
import sys
from pathlib import Path

import numpy as np


TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
if str(SOURCE_DIR) not in sys.path:
    sys.path.insert(0, str(SOURCE_DIR))

REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"
SPEC_FILE = TASK_DIR / "fixtures" / "workload_spec.json"


def _read_spec() -> dict[str, object]:
    return json.loads(SPEC_FILE.read_text(encoding="utf-8"))


def _make_particles(spec: dict[str, object]) -> dict[str, tuple[np.ndarray, str]]:
    seed = int(spec["seed"])
    shape = tuple(int(value) for value in spec["lattice_shape"])
    left = np.asarray(spec["domain_left"], dtype=np.float64)
    right = np.asarray(spec["domain_right"], dtype=np.float64)
    spacing = (right - left) / np.asarray(shape, dtype=np.float64)
    rng = np.random.default_rng(seed)

    positions = []
    for i in range(shape[0]):
        for j in range(shape[1]):
            for k in range(shape[2]):
                index = np.asarray((i, j, k), dtype=np.float64)
                point = left + (index + 0.5) * spacing
                if (i, j, k) != tuple(value // 2 for value in shape):
                    point = point + rng.uniform(-1.0, 1.0, 3) * spacing * float(
                        spec["jitter_fraction"]
                    )
                positions.append(point)

    positions = np.asarray(positions, dtype=np.float64)
    centered = positions - 0.5 * (left + right)
    normalized = centered / (right - left)
    masses = 1.0 + 0.12 * np.sin(5.0 * normalized[:, 0]) ** 2
    center_index = len(masses) // 2
    masses[center_index] *= float(spec["central_mass_multiplier"])
    density = 2.0 * masses
    field = float(spec["field_scale"]) * (
        1.0
        + 0.25 * normalized[:, 0]
        + 0.18 * normalized[:, 1] ** 2
        + 0.10 * np.cos(3.0 * normalized[:, 2])
    )
    smoothing = np.full(len(masses), float(spec["smoothing_length"]))
    return {
        "particle_position_x": (positions[:, 0], "cm"),
        "particle_position_y": (positions[:, 1], "cm"),
        "particle_position_z": (positions[:, 2], "cm"),
        "particle_mass": (masses / 729.0, "g"),
        "density": (density, "g/cm**3"),
        "smoothing_length": (smoothing, "cm"),
        "tracer": (field, str(spec["field_units"])),
    }


def _summarize_samples(samples: list[float]) -> dict[str, float | int]:
    values = np.asarray(samples, dtype=np.float64)
    if values.size == 0 or not np.isfinite(values).all():
        raise ValueError("the scientific workflow produced a non-finite sample")
    return {
        "sample_count": int(values.size),
        "finite_fraction": _report_number(float(np.isfinite(values).mean())),
        "observed_range": _report_number(float(np.max(values) - np.min(values))),
        "sample_mean": _report_number(float(np.mean(values))),
    }


def _observe(spec: dict[str, object]) -> list[dict[str, object]]:
    import yt

    data = _make_particles(spec)
    ds = yt.load_particles(
        data,
        length_unit=1.0,
        bbox=np.asarray(
            (spec["domain_left"], spec["domain_right"]), dtype=float
        ).T,
        periodicity=(True, True, True),
    )
    ds.kernel_name = "cubic"
    observations = []
    normal = np.asarray((1.0, 2.0, 3.0), dtype=np.float64)
    normal /= np.linalg.norm(normal)
    for label, view_normal, grid_sizes in (
        ("configuration_a", 2, (5, 9, 17, 33)),
        ("configuration_b", normal, (5, 9, 17)),
    ):
        samples = []
        for grid_size in grid_sizes:
            plot_options = {}
            if not isinstance(view_normal, (int, np.integer)):
                plot_options["north_vector"] = np.asarray(
                    (0.0, 1.0, 0.0), dtype=np.float64
                )
            plot = yt.ProjectionPlot(
                ds,
                view_normal,
                ("io", "tracer"),
                width=(3.0, "cm"),
                center=ds.domain_center,
                buff_size=(grid_size, grid_size),
                **plot_options,
            )
            image = np.asarray(
                plot.frb[("io", "tracer")].to_value(), dtype=np.float64
            )
            if not np.isfinite(image).all():
                raise ValueError("the scientific workflow produced a non-finite image")
            samples.append(float(image[grid_size // 2, grid_size // 2]))
        observations.append({"workflow": label, **_summarize_samples(samples)})
    return observations


def _write_report(report: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(exist_ok=True)
    payload = json.dumps(report, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(payload, encoding="utf-8")
    print(payload, end="")
    return exit_code


def _report_number(value: float) -> float:
    """Remove machine-roundoff noise from the human-readable summary."""
    return float(f"{float(value):.12g}")


def main() -> int:
    try:
        observations = _observe(_read_spec())
        if not observations:
            raise ValueError("the workflow did not produce finite summaries")
        report = {
            "schema_version": "1.0",
            "status": "workflow_completed",
            "operation": "particle-field visualization",
            "observations": observations,
            "summary": {
                "workflow_count": len(observations),
                "all_finite": True,
            },
        }
        return _write_report(report, 0)
    except Exception as exc:  # noqa: BLE001 - report runner failures explicitly.
        return _write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "operation": "particle-field visualization",
                "message": "the workflow could not be completed",
            },
            2,
        )


if __name__ == "__main__":
    raise SystemExit(main())

